#include "runtime/interpreter.hpp"
#include <chrono>
#include <iostream>
namespace {int checks=0;void run(const std::string& source,const penta::runtime::ExecutionOptions& options,bool success=true){++checks;const auto result=penta::runtime::execute(source,{},options);if(result.ok()==success)return;for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<" near "<<source.substr(d.span.offset,100)<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<" near "<<source.substr(d.span.offset,100)<<'\n';throw std::runtime_error("Extended science language fixture failed.");}}
int main(int argc,char**argv){penta::runtime::ExecutionOptions options;options.dataDirectory=std::filesystem::temp_directory_path()/("penta-science-extended-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(options.dataDirectory);options.odeCacheDirectory=options.dataDirectory/"kernels";options.maxOperations=100000000;if(argc>1)options.numericModuleDirectory=std::filesystem::absolute(argv[1]);try{
    run(R"(vector x=[1,2,3,4,5,6,7];record spectrum=fft(x);record restored=ifft(spectrum);assert(norm(restored.real-x')<1e-11);matrix values=[1,2,3,4,5,6,7;2,3,4,5,6,7,8];record matrix_spectrum=fft(values,options(axis=2,nfft=11));record inverse=ifft(matrix_spectrum,options(axis=2));assert(size(inverse.real,1)==2);assert(size(inverse.real,2)==11);assert(norm(inverse.real(:,1:7)-values,"fro")<1e-11);)",options);
    run(R"(vector t=0:0.01:1.26;vector x=sin(7*t)+0.2*cos(17*t);record s=spectrogram(x,options(segment=15,overlap=8,nfft=17,fs=100));matrix restored=istft(s);assert(norm(restored-x')<1e-10);record psd=pwelch(x,options(segment=31,nfft=37,fs=100,window="hamming"));assert(size(psd.power,1)==19);record coherent=mscohere(x,2*x,options(segment=31,nfft=37));assert(norm(coherent.coherence-ones(size(coherent.coherence,1),1))<1e-10);)",options);
    run(R"(record coefficients=butter(4,10,options(fs=100,type="low"));vector constant=2*ones(1,100);matrix smoothed=filtfilt(coefficients.b,coefficients.a,constant);assert(norm(smoothed-constant)<1e-10);record state=filterstate([0.5,0.5],[1],[1,0,0,0]);assert(state.values==[0.5,0.5,0,0]);assert(state.final_state(1)==0);)",options);
    run(R"(vector x=[0,2,2,0,0,3,0];record peaks=findpeaks(x,options(min_prominence=1));assert(peaks.count==2);assert(peaks.indices(1)==2);assert(peaks.plateau_sizes(1)==2);assert(peaks.refined_indices(1)==2.5);assert(peaks.prominences(2)==3);record refined=peakprops([-1.0625,2.4375,3.9375,3.4375,0.9375]);assert(abs(refined.refined_values(1)-4)<1e-12);assert(abs(refined.refined_indices(1)-3.25)<1e-12);)",options);
    run(R"(vector p=[0.25,0.5,0.75];matrix q=distinv("gamma",p,options(shape=2,scale=3));assert(norm(distcdf("gamma",q,options(shape=2,scale=3))-p)<1e-9);record a=distrand("normal",1,2048,options(seed=42));record b=distrand("normal",1,2048,options(seed=42));assert(norm(a.values-b.values)==0);assert(a.seed==42);matrix average=mean(a.values);assert(abs(average(1))<0.1);matrix counts=distinv("poisson",p,options(lambda=3));assert(norm(counts-round(counts))==0);assert(distpdf("gamma",-1,options(shape=2))==0);)",options);
    run(R"(native function real shifted_mean(matrix<1,8> values,real offset){matrix<1,1> total=sum(values);return total(1)/8+offset;}vector data=1:8;record one=bootstrap(data,options(statistic=shifted_mean,parameters=options(offset=0),replicates=64,seed=42,method="moving_block",block_length=2,threads=1));record many=bootstrap(data,options(statistic=shifted_mean,parameters=options(offset=0),replicates=64,seed=42,method="moving_block",block_length=2,threads=4));assert(norm(one.estimates-many.estimates)==0);assert(one.cache_key==many.cache_key);assert(many.cache_hit);record changed=bootstrap(data,options(statistic=shifted_mean,parameters=options(offset=1),replicates=64,seed=42,method="moving_block",block_length=2,threads=2));assert(changed.cache_key==many.cache_key);assert(norm(changed.estimates-many.estimates-ones(64,1))<1e-12);record intact=bootstrap(data,options(method="circular_block",block_length=8,replicates=32,seed=7));assert(norm(intact.estimates-4.5*ones(32,1))<1e-12);record stationary=bootstrap(data,options(method="stationary",block_length=3,replicates=32,seed=7));assert(stationary.block_length==3);)",options);
    run(R"(record bad=bootstrap([1,2,3],options(method="moving_block",block_length=4));)",options,false);
    run(R"(matrix bad=filtfilt([0.5,0.5],[1],[1,2]);)",options,false);
    std::cout<<"PASS "<<checks<<" extended science language checks\n";
}catch(const std::exception&e){std::cerr<<"FAIL after "<<checks<<": "<<e.what()<<'\n';return 1;}std::error_code ignored;std::filesystem::remove_all(options.dataDirectory,ignored);}
